import { useEffect, useState } from 'react';
import { useAuth } from '@/contexts/AuthContext';
import { supabase } from '@/integrations/supabase/client';
import { Users, LogOut } from 'lucide-react';

const STORAGE_KEY = 'apex_parent_session';

/**
 * Banner shown when a parent has signed into the student's account via a
 * magic link generated by the parent-access flow. The flag is set in
 * AuthCallback when the URL contains ?parent=1.
 */
export function ParentSessionBanner() {
  const { user, signOut } = useAuth();
  const [active, setActive] = useState(false);
  const [studentName, setStudentName] = useState<string>('');

  useEffect(() => {
    if (!user) {
      setActive(false);
      return;
    }
    setActive(sessionStorage.getItem(STORAGE_KEY) === '1');
  }, [user]);

  useEffect(() => {
    if (!active || !user) return;
    let cancelled = false;
    (async () => {
      const { data } = await supabase
        .from('profiles')
        .select('full_name, email')
        .eq('id', user.id)
        .maybeSingle();
      if (cancelled) return;
      setStudentName(data?.full_name || data?.email || '');
    })();
    return () => {
      cancelled = true;
    };
  }, [active, user]);

  if (!active || !user) return null;

  const handleExit = async () => {
    sessionStorage.removeItem(STORAGE_KEY);
    await signOut();
  };

  return (
    <div
      className="fixed top-0 inset-x-0 z-[60] flex items-center justify-between gap-3 px-4 py-2 text-xs sm:text-sm"
      style={{
        background: 'linear-gradient(90deg, rgba(240,192,64,0.95), rgba(240,192,64,0.85))',
        color: '#0d1f18',
        paddingTop: 'calc(env(safe-area-inset-top) + 8px)',
      }}
      role="status"
    >
      <div className="flex items-center gap-2 min-w-0">
        <Users className="h-4 w-4 shrink-0" />
        <span className="truncate font-medium">
          Estás viendo la cuenta de <strong>{studentName || '…'}</strong> como familiar
        </span>
      </div>
      <button
        type="button"
        onClick={handleExit}
        className="flex items-center gap-1 font-semibold hover:opacity-80 shrink-0"
      >
        <LogOut className="h-4 w-4" />
        Salir
      </button>
    </div>
  );
}